B.aWT=new A.bu([B.ol,"Nonchalante",B.om,"Jovial",B.on,"Tendre",B.oo,"Taquin",B.op,"Sage",B.ui,"Curieux",B.oq,"P\xe9tillante",B.uj,"Bavard",B.or,"Timide",B.os,"Exigeant"],A.ah("bu<mC,h>"))
B.axU=s(["Mouais. C\u2019est juste.","Pas mal, hein.","Ok, tu g\xe8res.","Tranquille. Bonne r\xe9ponse.","Bon. Je suis presque impressionn\xe9e."],t.s)
B.aAo=s(["Bof. \xc7a arrive.","Rat\xe9. On s\u2019en remet.","Pas grave, on refait.","Hmm. Presque. Enfin\u2026 non."],t.s)
B.aAt=s(["{n} d\u2019affil\xe9e. Tu forces un peu, l\xe0.","{n} de suite\u2026 Ok, respect.","Encore ? {n}. Tu ne te fatigues jamais ?"],t.s)
B.azI=s(["Z\xe9ro faute. Je ne dis rien, mais c\u2019est fort.","Sans faute. Tu m\u2019as presque r\xe9veill\xe9e."],t.s)
B.aI_=s(["C\u2019est fait. Proprement.","Pas mal du tout. Je retourne m\u2019asseoir."],t.s)
B.aAK=s(["Laborieux, mais termin\xe9. \xc7a compte.","On a vu mieux, on a vu pire. Reviens demain."],t.s)
B.aEj=s(["\xc9coute. Une fois suffit, normalement.","Tends l\u2019oreille. Je ne r\xe9p\xe8te pas\u2026 si, je r\xe9p\xe8te."],t.s)
B.aNo=s(["\xc0 toi. Sans stress.","R\xe9p\xe8te apr\xe8s moi. Tranquille."],t.s)
B.aTV=new A.bu([B.c2,B.axU,B.c3,B.aAo,B.ce,B.aAt,B.cf,B.azI,B.cg,B.aI_,B.ch,B.aAK,B.ci,B.aEj,B.cj,B.aNo],t.Sb)
B.aAx=s(["H\xe9\xe9\xe9 ! C\u2019est \xe7a m\xeame !","Voil\xe0 ! Tu as tout compris !","Bravo, la famille !","Ha ha ! Trop fort !","\xc7a, c\u2019est du bon travail !"],t.s)
B.ay7=s(["A\xefe ! Ce n\u2019est rien, on recommence !","\xc7a arrive \xe0 tout le monde, m\xeame \xe0 moi !","Pas grave, on rit et on reprend !","Presque ! La prochaine est pour toi !"],t.s)
B.aqs=s(["{n} de suite ! On ne t\u2019arr\xeate plus !","{n} ! Le march\xe9 entier t\u2019applaudit !","Combo de {n} ! Je danse pour toi !"],t.s)
B.atX=s(["Sans faute ! Aujourd\u2019hui, c\u2019est toi le patron !","Z\xe9ro erreur ! \xc7a se f\xeate !"],t.s)
B.apN=s(["Le\xe7on boucl\xe9e ! Tu avances bien, dis donc !","C\u2019est fait ! Je suis fier de toi !"],t.s)
B.aHa=s(["C\u2019\xe9tait dur, mais tu as tenu ! \xc7a, c\u2019est le courage !","Tu n\u2019as pas l\xe2ch\xe9 ! Demain ce sera plus facile !"],t.s)
B.aCB=s(["\xc9coute bien, c\u2019est joli \xe0 entendre !","Ouvre grand les oreilles !"],t.s)
B.aK2=s(["\xc0 toi ! Dis-le bien fort !","R\xe9p\xe8te avec moi, sans g\xeane !"],t.s)
B.aTY=new A.bu([B.c2,B.aAx,B.c3,B.ay7,B.ce,B.aqs,B.cf,B.atX,B.cg,B.apN,B.ch,B.aHa,B.ci,B.aCB,B.cj,B.aK2],t.Sb)
B.aKl=s(["C\u2019est bien, continue comme \xe7a.","Tr\xe8s bien. Je savais que tu y arriverais.","Bonne r\xe9ponse, doucement mais s\xfbrement.","Tu progresses, je le vois.","Parfait. Prends ton temps."],t.s)
B.auy=s(["Ce n\u2019est pas grave. On reprend ensemble.","Doucement. L\u2019erreur fait partie du chemin.","Regarde bien la r\xe9ponse, tu la retiendras.","Courage, tu y es presque."],t.s)
B.ap4=s(["{n} bonnes r\xe9ponses de suite. Je suis fi\xe8re de toi.","{n} d\u2019affil\xe9e, sans te presser. Bravo.","{n} ! Tu vois que tu peux."],t.s)
B.aHi=s(["Bravo pour ce sans-faute, vraiment.","Pas une erreur. Quel beau travail."],t.s)
B.aDX=s(["Le\xe7on termin\xe9e. Chaque jour un peu plus.","C\u2019est fait. Tu avances \xe0 ton rythme, et c\u2019est le bon."],t.s)
B.aJu=s(["Tu as tenu jusqu\u2019au bout, et c\u2019est \xe7a qui compte.","Ce n\u2019\xe9tait pas facile. Repose-toi, on reprend demain."],t.s)
B.auA=s(["\xc9coute tranquillement.","\xc9coute, autant de fois que tu veux."],t.s)
B.aFQ=s(["R\xe9p\xe8te apr\xe8s moi, doucement.","\xc0 ton tour, sans te presser."],t.s)
B.aTL=new A.bu([B.c2,B.aKl,B.c3,B.auy,B.ce,B.ap4,B.cf,B.aHi,B.cg,B.aDX,B.ch,B.aJu,B.ci,B.auA,B.cj,B.aFQ],t.Sb)
B.asf=s(["Eh, tu triches ou quoi ? C\u2019est juste !","Pas mal pour quelqu\u2019un qui dormait hier.","Bien vu ! Je te croyais moins rapide.","Correct ! Tu m\u2019\xe9tonnes, l\xe0.","Bonne r\xe9ponse. Ne prends pas la grosse t\xeate."],t.s)
B.aoY=s(["Oups ! Je garde \xe7a pour moi, promis.","Rat\xe9 ! Mais j\u2019ai vu pire\u2026 moi, par exemple.","Ha ! Presque. Presque, hein.","Ce n\u2019est pas \xe7a. Je ne dirai rien \xe0 personne."],t.s)
B.asz=s(["{n} de suite ? Tu veux ma place ou quoi ?","{n} ! D\u2019accord, j\u2019arr\xeate de te taquiner.","Combo de {n}. Bon, l\xe0, chapeau."],t.s)
B.aoO=s(["Sans faute ? Tu avais les r\xe9ponses dans la poche, avoue.","Z\xe9ro erreur. Je n\u2019ai m\xeame pas de blague."],t.s)
B.aBp=s(["Termin\xe9 ! Tu vois, quand tu veux.","Le\xe7on finie. Je te taquine, mais c\u2019est bien."],t.s)
B.aHm=s(["Tu as transpir\xe9, mais c\u2019est pli\xe9 !","Dur, dur\u2026 mais tu n\u2019as pas fui. Respect."],t.s)
B.atN=s(["\xc9coute bien, je ne le dirai pas deux fois. Si, bon, d\u2019accord.","Ouvre tes oreilles, petit malin."],t.s)
B.aLN=s(["\xc0 toi ! Et articule, hein.","R\xe9p\xe8te apr\xe8s moi, sans rire."],t.s)
B.aTG=new A.bu([B.c2,B.asf,B.c3,B.aoY,B.ce,B.asz,B.cf,B.aoO,B.cg,B.aBp,B.ch,B.aHm,B.ci,B.atN,B.cj,B.aLN],t.Sb)
B.aw6=s(["C\u2019est bien, mon enfant.","Voil\xe0. Tu parles comme chez nous.","Bonne r\xe9ponse. La patience paie.","C\u2019est juste. Cette langue te va bien.","Tr\xe8s bien. Tu \xe9coutes, donc tu apprends."],t.s)
B.aI9=s(["Ce n\u2019est rien. On tombe, on se rel\xe8ve.","Doucement, mon enfant. Recommence.","M\xeame le vieux lion a appris \xe0 marcher.","L\u2019erreur d\u2019aujourd\u2019hui est le savoir de demain."],t.s)
B.ayq=s(["{n} de suite. Tu as de la t\xeate, mon enfant.","{n} bonnes r\xe9ponses. Le village sera fier.","{n} ! Continue, je t\u2019\xe9coute."],t.s)
B.atZ=s(["Pas une faute. Je n\u2019ai rien \xe0 ajouter, c\u2019est parfait.","Sans faute. Va, tu as bien m\xe9rit\xe9 ton repas."],t.s)
B.aMA=s(["La le\xe7on est finie. Petit \xe0 petit, la langue entre.","C\u2019est bien. Reviens demain, je serai l\xe0."],t.s)
B.aG8=s(["C\u2019\xe9tait long, mais tu n\u2019es pas parti. C\u2019est \xe7a, apprendre.","Tu as pein\xe9, tu as fini. Voil\xe0 la vraie force."],t.s)
B.aqP=s(["\xc9coute comme on \xe9coute un conte.","Tends l\u2019oreille, mon enfant."],t.s)
B.aHL=s(["R\xe9p\xe8te apr\xe8s moi, mon enfant.","\xc0 toi. Parle sans peur."],t.s)
B.aTT=new A.bu([B.c2,B.aw6,B.c3,B.aI9,B.ce,B.ayq,B.cf,B.atZ,B.cg,B.aMA,B.ch,B.aG8,B.ci,B.aqP,B.cj,B.aHL],t.Sb)
B.aFC=s(["Ouiii ! C\u2019est la bonne !","Trop bien ! Tu m\u2019apprends, apr\xe8s ?","Gagn\xe9 !","Waouh, tu sais d\xe9j\xe0 \xe7a ?","Bonne r\xe9ponse ! Encore une !"],t.s)
B.arA=s(["Oh\u2026 ce n\u2019\xe9tait pas \xe7a. Moi aussi je me trompe.","Rat\xe9 ! On r\xe9essaie ?","Zut ! La prochaine, on l\u2019aura.","Ce n\u2019est pas grave, la ma\xeetresse dit qu\u2019on apprend comme \xe7a."],t.s)
B.aJI=s(["{n} de suite ! C\u2019est trop fort !","{n} ! Je veux faire pareil !","Combo de {n} ! On continue ?"],t.s)
B.aGQ=s(["Sans faute ! Tu auras une bonne note !","Z\xe9ro faute ! C\u2019est comme \xe0 l\u2019\xe9cole, mais en mieux !"],t.s)
B.av6=s(["Fini ! On en fait une autre ?","Le\xe7on termin\xe9e ! J\u2019ai appris plein de choses avec toi."],t.s)
B.ayE=s(["C\u2019\xe9tait difficile, mais on a fini !","Ouf ! On a r\xe9ussi quand m\xeame !"],t.s)
B.aGz=s(["\xc9coute, \xe9coute ! C\u2019est quoi, ce mot ?","Chut\u2026 on \xe9coute."],t.s)
B.aGk=s(["\xc0 toi de parler !","R\xe9p\xe8te ! Moi aussi je m\u2019entra\xeene."],t.s)
B.aTS=new A.bu([B.c2,B.aFC,B.c3,B.arA,B.ce,B.aJI,B.cf,B.aGQ,B.cg,B.av6,B.ch,B.ayE,B.ci,B.aGz,B.cj,B.aGk],t.Sb)
B.aBT=s(["Magnifique ! \xc7a sonne juste !","Oh l\xe0 l\xe0, quelle oreille !","Bravo ! On dirait une chanson.","C\u2019est \xe7a ! En plein dans le ton.","Parfait, parfait, parfait !"],t.s)
B.av1=s(["Fausse note ! Ce n\u2019est rien, on reprend.","Oups ! M\xeame les stars r\xe9p\xe8tent.","Pas tout \xe0 fait. On la refait, en rythme.","Rat\xe9, mais avec style !"],t.s)
B.aoA=s(["{n} de suite ! Quel tempo !","{n} ! Le public est debout !","Combo de {n} ! Tu es en tourn\xe9e ou quoi ?"],t.s)
B.aEk=s(["Sans fausse note ! Ovation debout !","Z\xe9ro faute ! Rappel, rappel !"],t.s)
B.ao5=s(["Le\xe7on termin\xe9e ! Belle prestation.","C\u2019est dans la bo\xeete ! Bravo l\u2019artiste."],t.s)
B.aqF=s(["Quelques fausses notes, mais tu as fini le concert !","Pas facile, ce morceau. Tu l\u2019as tenu jusqu\u2019au bout."],t.s)
B.ato=s(["\xc9coute la m\xe9lodie du mot.","\xc9coute bien : chaque mot a sa musique."],t.s)
B.aIb=s(["\xc0 toi le micro !","Chante-le\u2026 enfin, dis-le !"],t.s)
